      strokeWidth: 0.15
    })
  ],
  color: {
    range: ["#f9ddda", "#f2b9c4", "#e597b9", "#ce78b3", "#ad5fad", "#834ba0", "#573b88"],
    unknown: "#f2f2f2",
    type: "log", 
    legend: true,
    label: "Total obligations",
    tickFormat: d =&gt; d3.format("$0.2s")(d).replace("G", "B"),
